<body><main class="wrap"><a class="back" href="{{ route('public.menu',['subdomain'=>$venue->subdomain]) }}">&larr; Voltar ao cardápio</a><article class="product"><section>@php($allImages = collect([$product->image_path])->filter()->merge($product->images->pluck('path')))<img id="mainImage" class="main-image" src="{{ $allImages->isNotEmpty() ? route('public.media',['subdomain'=>$venue->subdomain,'category'=>'products','filename'=>basename($allImages->first())]) : '' }}" alt="{{ $product->name }}">@if($allImages->count()>1)<div class="thumbs">@foreach($allImages as $path)<img class="thumb @if($loop->first) active @endif" src="{{ route('public.media',['subdomain'=>$venue->subdomain,'category'=>'products','filename'=>basename($path)]) }}" alt="{{ $product->name }} - imagem {{ $loop->iteration }}">@endforeach</div>@endif</section><section><p style="color:var(--brand);font-weight:900;text-transform:uppercase;letter-spacing:.1em;font-size:12px">{{ $venue->name }}</p><h1>{{ $product->name }}</h1>@if($product->description)<p class="description">{{ $product->description }}</p>@endif<p class="price">R$ {{ number_format((float)$product->price,2,',','.') }}</p>@if($product->optionGroups->isNotEmpty())<div class="options"><strong>Personalize seu pedido</strong>@foreach($product->optionGroups as $group)<h3>{{ $group->name }}</h3><small>{{ $group->minimum ? 'Escolha no mínimo '.$group->minimum : 'Opcional' }} · máximo {{ $group->maximum }}</small>@endforeach</div>@endif<a class="buy" href="{{ route('public.menu',['subdomain'=>$venue->subdomain,'produto'=>$product->id]) }}">{{ $product->optionGroups->isNotEmpty() ? 'Escolher opções' : 'Comprar' }}</a></section></article></main><script>document.querySelectorAll('.thumb').forEach(thumb=>thumb.addEventListener('click',()=>{document.getElementById('mainImage').src=thumb.src;document.querySelectorAll('.thumb').forEach(item=>item.classList.remove('active'));thumb.classList.add('active')}));</script></body></html>
